"""Fulfillment endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.errors import OrderNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_non_negative_int, require_positive_int, require_str
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


class FulfilmentController:
    def __init__(self, service: OrderService, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository,
                 orders: InMemoryOrderRepository) -> None:
        self._service = service
        self._customers = customers
        self._catalog = catalog
        self._stock = stock
        self._orders = orders

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            order = self._service.get_order(order_id)
        except OrderNotFound:
            return not_found("order")

        if order.status == "cancelled":
            return Response(409, {"error": f"order {order_id} is cancelled"})

        customer = self._customers.get(order.customer_id)
        customer_name = customer.name if customer else ""

        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            product_name = product.name if product else ""
            lines.append({"sku": item.sku, "name": product_name, "quantity": item.quantity})

        return Response(200, {
            "order_id": order.order_id,
            "customer_name": customer_name,
            "lines": lines,
        })

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            threshold_int = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)

        stock_levels = self._stock.all_levels()
        low_stock_products = []

        for product in self._catalog.list_all():
            if product.active and stock_levels.get(product.sku, 0) < threshold_int:
                low_stock_products.append({
                    "sku": product.sku,
                    "name": product.name,
                    "on_hand": stock_levels.get(product.sku, 0),
                })

        low_stock_products.sort(key=lambda p: (p["on_hand"], p["sku"]))

        return Response(200, {"products": low_stock_products})

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)

        product = self._catalog.get(sku)
        if product is None:
            return not_found("product")

        new_level = self._stock.get(sku) + quantity
        self._stock.set(sku, new_level)

        return Response(200, {"sku": sku, "on_hand": new_level})

    def handle_fulfilment_summary(self) -> Response:
        orders = self._orders.list_all()
        open_orders = sum(1 for order in orders if order.status != "cancelled")
        units_to_pick = sum(item.quantity for order in orders if order.status != "cancelled"
                            for item in order.items)

        stock_levels = self._stock.all_levels()
        low_stock_products = sum(1 for product in self._catalog.list_all()
                                 if product.active and stock_levels.get(product.sku, 0) < 5)

        return Response(200, {
            "open_orders": open_orders,
            "units_to_pick": units_to_pick,
            "low_stock_products": low_stock_products,
        })
